// Store output_3_1 from the GPT/Codex CLI server
const staticData = $getWorkflowStaticData('global');
const item = $input.first().json || {};
const OUTPUT_KEY = "output_3_1";
const STAGE_ID   = "output_3_1";

if (item.paused === true) {
  throw new Error(STAGE_ID + ': PAUSED ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â GPT/Codex CLI usage limit reached. '
    + 'No API fallback was used and nothing was billed. Wait for the limit to reset, '
    + 'delete PAUSED.flag next to claude_agent_server.py, then re-run this workflow. '
    + 'Completed stages replay from checkpoint and are not regenerated.');
}
if (item.success === false) {
  throw new Error(STAGE_ID + ': GPT/Codex CLI server error ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â ' + (item.error || 'unknown'));
}

const text = String(item.output || '').trim();
if (!text) {
  throw new Error(STAGE_ID + ': server returned success with an empty output.');
}

staticData[OUTPUT_KEY] = text;

const titleKeyword = staticData.title_keyword || item.title_keyword || '';
const result = {
  ...item,
  [OUTPUT_KEY]: text,
  doc_file_id: staticData.doc_file_id || item.doc_file_id || '',
  title_keyword: titleKeyword,
  high_end_products: staticData.high_end_products || item.high_end_products || '',
  mid_and_afford_products: staticData.mid_and_afford_products || item.mid_and_afford_products || ''
};

return [{ json: result }];

