};

return [{ json: result }];

// Loop complete ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â increment row counter and save to persistent storage
const staticData = $getWorkflowStaticData('global');
const currentRow = staticData.current_processing_row || 2;
const nextRow = currentRow + 1;
staticData.current_processing_row = nextRow;

// Keep promptsLoaded flag ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â prompts stay in memory for next cycle
staticData.promptsLoaded = true;

// Clear cycle-specific data but keep prompt variables
const promptIds = [
  'prompt_1', 'prompt_1_1', 'prompt_2', 'prompt_2_1',
  'prompt_4', 'prompt_4_1', 'prompt_4_2', 'prompt_4_3',
  'prompt_5', 'prompt_5_1', 'prompt_5_2', 'prompt_5_3',
  'prompt_5_4', 'prompt_5_5', 'prompt_5_6', 'prompt_5_7',
  'prompt_6', 'prompt_6_1', 'prompt_7', 'prompt_7_1',
  'prompt_8', 'prompt_9', 'prompt_9_1', 'prompt_10',
  'prompt_11', 'prompt_11_1'
];

// Clear keyword and output data but preserve prompts
const keysToKeep = [...promptIds, 'promptsLoaded', 'current_processing_row'];
for (const key of Object.keys(staticData)) {
  if (!keysToKeep.includes(key)) {
    delete staticData[key];
  }
}

return [{
  json: {
    loopComplete: true,
    nextRow: nextRow,
    message: 'Cycle complete. Row incremented to ' + nextRow + '. Restarting from Section 1.'
  }
}];

// Input from Spreadsheet File is JSON rows, one item per Excel row.
// Excel headers expected: TITLE KEYWORD, HIGH END PRODUCTS, MID AND AFFORD END PRODUCTS.
const staticData = $getWorkflowStaticData('global');
const currentRow = Number(staticData.current_processing_row || 2);
const rows = $input.all();
const rowIndex = currentRow - 2; // Excel row 2 = first JSON item after header row
const row = rows[rowIndex]?.json || {};

