  const clean = stripHtml(value) || label || titleCase(field);
  const attrs = `acf="${field}" data-acf="${field}" data-acf-key="${ACF_FIELDS.find(f => f.name === field)?.key || ''}" data-acf-type="${type}"`;
  if (/^Text$/i.test(type) || /True\/False/i.test(type)) {
    return `<p ${attrs}>${esc(clean)}</p>`;
  }
  if (/Textarea/i.test(type)) {
    return `<div ${attrs}>\n<pre>${esc(clean)}</pre>\n</div>`;
  }
  return `<div ${attrs}>\n<p>${esc(clean)}</p>\n</div>`;
}
function tableValue(text) {
  const rows = splitChunks(text, 7).map((x, i) => `<tr><td>${i + 1}</td><td>${esc(x)}</td></tr>`).join('\n');
  return `<table class="CSS_TABLE"><tbody>\n${rows}\n</tbody></table>`;
}

